UPDATE app_settings SET strict_rules = strict_rules || ARRAY['📸 รูป/วิดีโอ: ส่งเฉพาะเมื่อลูกค้าขอชัดๆ (ขอรูป/ตัวอย่าง/เมนู/แพ็กเกจ) — ถามเรื่องอื่น (ชิม/ค่าส่ง/เงื่อนไข/ราคาเฉยๆ) ห้ามแถมรูปเมนูหรือตัวอย่าง | ขอ "เมนู" เฉยๆ ไม่บอกประเภท → ถามก่อน (บุฟเฟ่ต์/ซุ้ม/โต๊ะจีน) ห้ามส่งรวม | ขอ "แพ็กเกจ/ราคา" → ส่งเฉพาะรูปแพ็ก ห้ามแถมเมนู/ตัวอย่างจัดงาน']
WHERE key='ai_config' AND NOT (strict_rules::text LIKE '%📸 รูป/วิดีโอ%');